mapper.select:
SELECT rd.ingredient_id,COALESCE(i.ingredient_name_std,i.ingredient_name_raw,rd.ingredient_name_raw) ingredient_name, i.base_unit master_unit,rd.base_unit, CASE WHEN rd.review_flag=0 THEN rd.qty_per_person*d.planned_servings END quantity, m.menu_name,d.menu_id,d.meal_date FROM (
SELECT #{meal.menu_id} menu_id,#{meal.planned_servings} planned_servings, COALESCE(#{meal.meal_date},#{date_from}) meal_date
) d LEFT JOIN the_full_order.tb_account_menu_master m ON m.account_id=#{account_id} AND m.menu_id=d.menu_id AND m.del_yn='N' LEFT JOIN the_full_order.tb_account_recipe_detail rd ON rd.account_id=m.account_id AND rd.menu_id=m.menu_id LEFT JOIN the_full_order.tb_account_ingredient_master i ON i.account_id=rd.account_id AND i.ingredient_id=rd.ingredient_id
